function tmParse(spec){
  var lines = spec.split(/\r?\n/);
  var blank='_', start='q0', accept='qa', reject='qr', tapeStr='', trans={};
  for(var i=0;i<lines.length;i++){
    var line=lines[i].trim();
    if(!line || line[0]==='#') continue;
    var m;
    if((m=line.match(/^tape:\s*(.*)$/))) tapeStr=m[1];
    else if((m=line.match(/^start:\s*(\S+)$/))) start=m[1];
    else if((m=line.match(/^accept:\s*(\S+)$/))) accept=m[1];
    else if((m=line.match(/^reject:\s*(\S+)$/))) reject=m[1];
    else if((m=line.match(/^blank:\s*(\S+)$/))) blank=m[1];
    else if((m=line.match(/^([^,]+),\s*([^ ]+)\s*->\s*([^,]+),\s*([^,]+),\s*([LRS])$/))){
      trans[m[1].trim()+'\u0000'+m[2].trim()]={state:m[3].trim(), write:m[4].trim(), dir:m[5].trim()};
    } else throw new Error('无法解析规则: '+line);
  }
  return {blank:blank, start:start, accept:accept, reject:reject, transitions:trans, tape:tapeStr};
}
function tmRun(program, opts){
  opts=opts||{};
  var maxSteps=opts.maxSteps||1000, blank=program.blank;
  var tape=String(program.tape||'').split('');
  if(opts.initTape!==undefined) tape=String(opts.initTape).split('');
  var head=opts.head||0, state=program.start, steps=0, trace=[];
  function snap(){ trace.push({state:state, head:head, tape:tape.join('')}); }
  snap();
  while(steps<maxSteps){
    while(head<0){ tape.unshift(blank); head=0; }
    while(head>=tape.length){ tape.push(blank); }
    var key=state+'\u0000'+tape[head];
    var rule=program.transitions[key];
    if(!rule) return {steps:steps,status:'halt',state:state,head:head,tape:tape.join(''),trace:trace,accepted:state===program.accept};
    tape[head]=rule.write; state=rule.state;
    if(rule.dir==='L') head--; else if(rule.dir==='R') head++;
    steps++; snap();
    if(state===program.accept) return {steps:steps,status:'accept',state:state,head:head,tape:tape.join(''),trace:trace,accepted:true};
    if(state===program.reject) return {steps:steps,status:'reject',state:state,head:head,tape:tape.join(''),trace:trace,accepted:false};
  }
  return {steps:steps,status:'timeout',state:state,head:head,tape:tape.join(''),trace:trace,accepted:false};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tmParse:tmParse, tmRun:tmRun };
}
if (typeof window !== 'undefined') {
  window.TuringForgePure = { tmParse:tmParse, tmRun:tmRun };
}
